mapper.select:
SELECT  FROM workflow_run
WHERE workspace_id = #{workspaceId}
  AND workflow_id = #{workflowId}
  AND dedupe_key = #{dedupeKey}

SELECT  FROM workflow_run
WHERE workspace_id = #{workspaceId}
  AND workflow_id = #{workflowId}
  AND id = #{id}

SELECT  FROM workflow_run
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

SELECT  FROM workflow_run
WHERE workspace_id = #{workspaceId}
  AND workflow_id = #{workflowId}
  AND trigger_key = #{triggerKey}
  AND status = 'running'
ORDER BY id
LIMIT #{limit}

SELECT COALESCE(MAX(sequence_number) + 1, 0)
FROM workflow_step_run
WHERE workspace_id = #{workspaceId} AND workflow_run_id = #{workflowRunId}

mapper.update:
UPDATE workflow_run
SET current_node_id = #{nextNodeId}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'running'
  AND current_node_id = #{expectedNodeId}

UPDATE workflow_run
SET status = 'succeeded', current_node_id = NULL, finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status = 'running'
  AND current_node_id = #{expectedNodeId}

UPDATE workflow_run
SET status = #{status},
    failure_node_id = #{expectedNodeId},
    failure_code = #{failureCode},
    failure_message = #{failureMessage},
    finished_at = #{finishedAt}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND status IN ('queued', 'running', 'waiting')
  AND current_node_id = #{expectedNodeId}

mapper.select:
SELECT CURRENT_TIMESTAMP(6)
FROM workflow
WHERE workspace_id = #{workspaceId} AND id = #{workflowId}

SELECT 
FROM workflow_run wr
JOIN workflow_version v
  ON v.workspace_id = wr.workspace_id
 AND v.workflow_id = wr.workflow_id
 AND v.id = wr.workflow_version_id
WHERE wr.workspace_id = #{workspaceId}
  AND wr.workflow_id = #{workflowId}
  AND wr.started_at <= #{asOf}

    AND (wr.started_at < #{beforeStartedAt}
      OR (wr.started_at = #{beforeStartedAt} AND wr.id < #{beforeId}))

ORDER BY wr.started_at DESC, wr.id DESC
LIMIT #{limit}

SELECT 
FROM workflow_run wr
JOIN workflow_version v
  ON v.workspace_id = wr.workspace_id
 AND v.workflow_id = wr.workflow_id
 AND v.id = wr.workflow_version_id
WHERE wr.workspace_id = #{workspaceId}
  AND wr.workflow_id = #{workflowId}
  AND wr.id = #{id}

SELECT  FROM workflow_step_run
WHERE workspace_id = #{workspaceId} AND workflow_run_id = #{workflowRunId}
ORDER BY sequence_number, id
